#[path="../triangular-witness/core.rs"]mod core;
#[path="../triangular-witness/cost.rs"]mod cost;
#[path="../canonical-root/root.rs"]mod root;
#[path="../triangular-witness/geometry.rs"]mod geometry;
#[path="../triangular-witness/action.rs"]mod action;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng};
#[derive(Clone,Debug)]struct Proof{excluded:bool,k:u64,w:Vec<u64>}
fn prove(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp)->Proof{let mut basis:Vec<Option<(Vec<u64>,Vec<u64>)>>=vec![None;n];for(i,(v,b))in rows.iter().enumerate(){let mut a=v.clone();a.push(*b);let mut w=vec![0;rows.len()];w[i]=1;for j in 0..n{if a[j]==0{continue}if let Some((q,z))=&basis[j]{let scale=a[j];for k in j..=n{a[k]=f.sub(a[k],f.mul(scale,q[k]));}for k in 0..w.len(){w[k]=f.sub(w[k],f.mul(scale,z[k]));}}else{let iv=f.inv(a[j]);for x in &mut a{*x=f.mul(*x,iv);}for x in &mut w{*x=f.mul(*x,iv);}basis[j]=Some((a.clone(),w.clone()));break}}
if a[..n].iter().all(|x|*x==0)&&a[n]!=0{let iv=f.inv(a[n]);for x in &mut w{*x=f.mul(*x,iv);}return Proof{excluded:true,k:1,w}}}let(a,w)=basis[n-1].as_ref().expect("unresolved branch");Proof{excluded:false,k:a[n],w:w.clone()}}
fn verify(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp,p:&Proof)->bool{if p.w.len()!=rows.len()||p.w.iter().any(|x|*x>=f.p)||p.k>=f.p{return false}let mut sum=vec![0;n];let mut rhs=0;for((a,b),&w)in rows.iter().zip(&p.w){for j in 0..n{sum[j]=f.add(sum[j],f.mul(w,a[j]));}rhs=f.add(rhs,f.mul(w,*b));}if p.excluded{sum.iter().all(|x|*x==0)&&rhs==1&&p.k==1}else{let mut e=vec![0;n];e[n-1]=1;sum==e&&rhs==p.k}}
fn main(){counted::disable();let(mut covers,mut exclusions,mut solves)=(0,0,0);for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let target=c.mul(&d,expected);let mut trace=None;for seed in 1..=3{let tr=core::solve(&c,pt,&d,&target,ell,sm,seed,true,true);if tr.answer.is_some(){trace=Some(tr);break}}let tr=trace.unwrap();let f=Fp::new(ell);let z=root::power_map(&f,5).0;let mut lambdas:Vec<_>=(1..5).map(|e|f.pow(z,e)).collect();lambdas.sort();lambdas.dedup();assert_eq!(lambdas.len(),4);let mut phi=Poly::one();for &l in &lambdas{phi=phi.mul(&Poly::x_minus(l,&f),&f);}assert_eq!(phi,Poly::from_coeffs(&[1;5]));let actual=action::witness(&c,tr.z,ell).unwrap().lambda;let mut anchors=vec![target];for _ in 0..16{anchors.push(c.add(anchors.last().unwrap(),&d));}for prim in &tr.primitives{assert!(geometry::exact(&c,&anchors[prim.a as usize],prim.t,&prim.points));}
for lambda in lambdas{let n=tr.points.len()+1;let mut rows=vec![];let mut public=vec![0;n];public[0]=1;rows.push((public,f.inv(sm)));let mut index=std::collections::BTreeMap::new();for(j,&(x,y))in tr.points.iter().enumerate(){let(mut xx,mut w)=(x,1);for _ in 0..5{assert!(index.insert((xx,y),(j,w)).is_none());let ny=c.fp.neg(y);if ny!=y{assert!(index.insert((xx,ny),(j,f.neg(w))).is_none());}xx=c.fp.mul(xx,tr.z);w=f.mul(w,lambda);}}for prim in &tr.primitives{let mut v=vec![0;n];v[n-1]=1;for xy in &prim.points{let &(j,w)=index.get(xy).unwrap();v[j]=f.add(v[j],w);}rows.push((v,f.neg(prim.a)));}let proof=prove(&rows,n,&f);assert!(verify(&rows,n,&f,&proof));let mut bad=proof.clone();bad.w[0]=f.add(bad.w[0],1);assert!(!verify(&rows,n,&f,&bad));if lambda==actual{assert!(!proof.excluded);assert_eq!(proof.k,expected);}if proof.excluded{exclusions+=1}else{assert_eq!(proof.k,expected);solves+=1;}println!("BRANCH\tp={p}\tsm={sm}\tcase={case}\tlambda={lambda}\tproof={proof:?}");}covers+=1;}}}assert_eq!(covers,12);eprintln!("PASS covers={covers} branches={} exclusions={exclusions} scalar_proofs={solves} exact_matrix_certificates=true weight_mutations_rejected=48 root_product_complete=true actual_action_reference_consistent=true no_cost_claim=true independent_verification=false",exclusions+solves);}
